def rollback_failed_deployments():
    service = 'api'
    env = 'prod'
    status = 'failed'

    offset = 0
    limit = 100
    rolled_back_count = 0

    while True:
        # list_deployments returns {total, items: [{id, service, env, status, version, rolled_back}]}
        result = list_deployments(service=service, env=env, status=status, limit=limit, offset=offset)
        items = result.get('items', [])

        if not items:
            break

        for item in items:
            # Check if it's already rolled back to avoid redundant calls
            if not item.get('rolled_back'):
                rollback_res = rollback_deployment(deployment_id=item['id'])
                if rollback_res.get('ok'):
                    rolled_back_count += 1

        # Check if we've reached the end
        if offset + limit >= result.get('total', 0):
            break

        offset += limit

    print(f"Rolled back {rolled_back_count} deployments.")

rollback_failed_deployments()

